public interface IOrderGateway {                    // domain contract
    Task<OrderStatusResult> GetStatusAsync(string orderId, CancellationToken ct);
}

public sealed class OrderGateway : IOrderGateway {
    private readonly IRequestClient<CheckOrderStatus> _client;
    public OrderGateway(IRequestClient<CheckOrderStatus> client) => _client = client;

    public async Task<OrderStatusResult> GetStatusAsync(string orderId, CancellationToken ct)
        => (await _client.GetResponse<OrderStatusResult>(new { orderId }, ct)).Message;
}

