public sealed class InventoryGateway : IAsyncDisposable {   // hand-written
    private readonly IChannel _channel;                       // RabbitMQ.Client
    private readonly ConcurrentDictionary<string, TaskCompletionSource<string>> _pending = new();
    public async Task<string> CheckStockAsync(string sku, CancellationToken ct) {
        var corrId = Guid.NewGuid().ToString();
        _pending[corrId] = new TaskCompletionSource<string>(TaskCreationOptions.RunContinuationsAsynchronously);
        await _channel.BasicPublishAsync("", "inventory.check", mandatory: false,
            basicProperties: new BasicProperties { ReplyTo = _replyQueue, CorrelationId = corrId },
            body: Encoding.UTF8.GetBytes(sku), cancellationToken: ct);
        return await _pending[corrId].Task.WaitAsync(ct);      // consumer completes it
    }
}
